 const [total,by_uf,by_kind,by_stage,by_component,by_year,by_age,occurrences,rels]=await Promise.all([
 countsBy(`SELECT count(*)::int AS count FROM items i WHERE ${f.where}`,f.values),grouped('i.uf'),grouped('i.kind'),
 countsBy(`SELECT p->>'stage' AS value,count(DISTINCT i.id)::int AS count FROM items i CROSS JOIN LATERAL jsonb_array_elements(i.positions) p WHERE ${f.where} GROUP BY 1 ORDER BY 1`,f.values),
 countsBy(`SELECT p->>'component' AS value,count(DISTINCT i.id)::int AS count FROM items i CROSS JOIN LATERAL jsonb_array_elements(i.positions) p WHERE ${f.where} GROUP BY 1 ORDER BY 1`,f.values),
 countsBy(`SELECT p->>'year_label' AS value,count(DISTINCT i.id)::int AS count FROM items i CROSS JOIN LATERAL jsonb_array_elements(i.positions) p WHERE ${f.where} GROUP BY 1 ORDER BY 1`,f.values),
 countsBy(`SELECT p->>'age_group' AS value,count(DISTINCT i.id)::int AS count FROM items i CROSS JOIN LATERAL jsonb_array_elements(i.positions) p WHERE ${f.where} GROUP BY 1 ORDER BY 1`,f.values),
 countsBy(`SELECT coalesce(sum(jsonb_array_length(i.positions)),0)::int AS count FROM items i WHERE ${f.where}`,f.values),
 countsBy(`SELECT DISTINCT r.id,r.relation_type,r.origin,r.technical_validation_status,r.pedagogical_review_status,r.publication_status FROM relations r JOIN relation_members m ON m.publication_id=r.publication_id AND m.relation_id=r.id JOIN items i ON i.publication_id=m.publication_id AND i.id=m.item_id WHERE ${f.where}`,f.values)]);
 const summarize=(key:string)=>{const m=new Map<string,number>();for(const r of rels)m.set(r[key],(m.get(r[key])??0)+1);return[...m].map(([value,count])=>({value,count})).sort((a,b)=>a.value.localeCompare(b.value));};
