 const nationalRows=options.unpaginated?await pool.query(`SELECT i.payload FROM items i WHERE ${where} ORDER BY ${f.rank} DESC,i.code NULLS LAST,i.id`,values):await pool.query(`SELECT i.payload FROM items i WHERE ${where} ORDER BY ${f.rank} DESC,i.code NULLS LAST,i.id LIMIT $${values.length+1} OFFSET $${values.length+2}`,[...values,nationalQuery.limit,(nationalQuery.page-1)*nationalQuery.limit]);
 const national=nationalRows.rows.map(r=>r.payload as Learning),nationalIds=national.map(i=>i.id),cover=await coverageRows(publication);
 const relationRows=nationalIds.length?(await pool.query(`SELECT DISTINCT r.payload FROM relations r JOIN relation_members m ON m.publication_id=r.publication_id AND m.relation_id=r.id WHERE r.publication_id=$1 AND m.item_id=ANY($2::text[]) ORDER BY r.payload`,[publication,nationalIds])).rows:[];
